import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const notificationCookie = 'notifications-enabled'

export default async function Home() {
  const enabled = (await cookies()).get(notificationCookie)?.value === 'true'

  async function toggleNotifications() {
    'use server'

    const cookieStore = await cookies()
    const currentlyEnabled = cookieStore.get(notificationCookie)?.value === 'true'
    cookieStore.set(notificationCookie, String(!currentlyEnabled), {
      httpOnly: true,
      sameSite: 'lax',
      path: '/',
    })
    refresh()
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

